alter table public.picture_caption_rounds add column voting_deadline timestamptz,add column voting_paused_remaining_seconds integer check(voting_paused_remaining_seconds is null or voting_paused_remaining_seconds>=0);

create or replace function public.materialize_picture_caption_candidates(p_round_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin insert into public.picture_caption_candidates(round_id,caption,normalized_caption,display_position) select p_round_id,min(submission.caption),lower(regexp_replace(btrim(submission.caption),'\s+',' ','g')),row_number() over(order by md5(p_round_id::text||lower(regexp_replace(btrim(submission.caption),'\s+',' ','g'))))::integer-1 from public.picture_caption_submissions submission where submission.round_id=p_round_id group by lower(regexp_replace(btrim(submission.caption),'\s+',' ','g')); insert into public.picture_caption_candidate_authors(candidate_id,party_member_id) select candidate.id,submission.party_member_id from public.picture_caption_candidates candidate join public.picture_caption_submissions submission on submission.round_id=candidate.round_id and lower(regexp_replace(btrim(submission.caption),'\s+',' ','g'))=candidate.normalized_caption where candidate.round_id=p_round_id; end; $$;

create function public.commit_picture_caption_voting_result(p_round_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare ballot_count integer; begin if exists(select 1 from public.picture_caption_round_results where round_id=p_round_id) then return false; end if; select count(*) into ballot_count from public.picture_caption_ballots where round_id=p_round_id; update public.picture_caption_candidates candidate set points=(select count(*) from public.picture_caption_ballots ballot where ballot.candidate_id=candidate.id) where candidate.round_id=p_round_id; update public.party_members member set score=score+1 from public.picture_caption_candidate_authors author join public.picture_caption_ballots ballot on ballot.candidate_id=author.candidate_id where author.party_member_id=member.id and ballot.round_id=p_round_id; insert into public.picture_caption_round_results(round_id,ballot_count) values(p_round_id,ballot_count); update public.picture_caption_rounds set state='completed',phase=null,voting_deadline=null,voting_paused_remaining_seconds=null where id=p_round_id; return true; end; $$;

create or replace function public.close_picture_captioning(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint,p_confirm_missing boolean) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; active_round public.picture_caption_rounds; eligible_count integer; submission_count integer; next_revision bigint; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.host_id=p_host_id and party.id=p_party_id and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; select round.* into active_round from public.picture_caption_rounds round where round.game_session_id=session_record.id and round.state='active' and round.phase='captioning' for update; if not found then raise exception using errcode='40001',message='captioning_closed'; end if; select count(*) into eligible_count from public.picture_caption_round_members where round_id=active_round.id; select count(*) into submission_count from public.picture_caption_submissions where round_id=active_round.id; if submission_count<eligible_count and not p_confirm_missing then raise exception using errcode='22023',message='close_confirmation_required'; end if; if submission_count>0 then perform public.materialize_picture_caption_candidates(active_round.id); update public.picture_caption_rounds set phase='voting',captioning_deadline=null,captioning_hard_deadline=null,paused_remaining_seconds=null,voting_deadline=now()+make_interval(secs=>voting_seconds) where id=active_round.id; else update public.picture_caption_rounds set state='completed',phase=null,captioning_deadline=null,captioning_hard_deadline=null,paused_remaining_seconds=null where id=active_round.id; end if; update public.game_sessions set revision=revision+1 where id=session_record.id returning revision into next_revision; insert into public.command_receipts values(p_host_id,p_command_id,'close_picture_captioning',jsonb_build_object('gameSessionId',session_record.id,'sessionRevision',next_revision)); return query select session_record.id,next_revision; end; $$;

create or replace function public.cast_picture_caption_ballot(p_player_id uuid,p_party_code text,p_command_id uuid,p_expected_revision bigint,p_candidate_id uuid) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; active_round public.picture_caption_rounds; member_id uuid; next_revision bigint; eligible_count integer; ballot_count integer; begin select response into existing from public.command_receipts where actor_id=p_player_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.code=upper(trim(p_party_code)) and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; select round.* into active_round from public.picture_caption_rounds round where round.game_session_id=session_record.id and round.state='active' and round.phase='voting' for update; if not found then raise exception using errcode='40001',message='voting_closed'; end if; if active_round.voting_deadline<=now() then perform public.commit_picture_caption_voting_result(active_round.id); update public.game_sessions set revision=revision+1 where id=session_record.id; raise exception using errcode='40001',message='voting_closed'; end if; select member.id into member_id from public.party_members member join public.picture_caption_round_members eligible on eligible.party_member_id=member.id and eligible.round_id=active_round.id where member.player_id=p_player_id and member.party_id=(select id from public.parties where code=upper(trim(p_party_code))); if not found then raise exception using errcode='P0002',message='eligible_member_not_found'; end if; if not exists(select 1 from public.picture_caption_candidates candidate where candidate.id=p_candidate_id and candidate.round_id=active_round.id) then raise exception using errcode='P0002',message='candidate_not_found'; end if; insert into public.picture_caption_ballots(round_id,party_member_id,candidate_id) values(active_round.id,member_id,p_candidate_id); select count(*) into eligible_count from public.picture_caption_round_members where round_id=active_round.id; select count(*) into ballot_count from public.picture_caption_ballots where round_id=active_round.id; if ballot_count>=eligible_count then perform public.commit_picture_caption_voting_result(active_round.id); end if; update public.game_sessions set revision=revision+1 where id=session_record.id returning revision into next_revision; insert into public.command_receipts values(p_player_id,p_command_id,'cast_picture_caption_ballot',jsonb_build_object('gameSessionId',session_record.id,'sessionRevision',next_revision)); return query select session_record.id,next_revision; exception when unique_violation then raise exception using errcode='40001',message='ballot_already_cast'; end; $$;

create or replace function public.close_picture_caption_voting(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint,p_confirm_missing boolean) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; active_round public.picture_caption_rounds; eligible_count integer; ballot_count integer; next_revision bigint; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.host_id=p_host_id and party.id=p_party_id and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; select round.* into active_round from public.picture_caption_rounds round where round.game_session_id=session_record.id and round.state='active' and round.phase='voting' for update; if not found then raise exception using errcode='40001',message='voting_closed'; end if; select count(*) into eligible_count from public.picture_caption_round_members where round_id=active_round.id; select count(*) into ballot_count from public.picture_caption_ballots where round_id=active_round.id; if ballot_count<eligible_count and active_round.voting_deadline>now() and not p_confirm_missing then raise exception using errcode='22023',message='close_confirmation_required'; end if; perform public.commit_picture_caption_voting_result(active_round.id); update public.game_sessions set revision=revision+1 where id=session_record.id returning revision into next_revision; insert into public.command_receipts values(p_host_id,p_command_id,'close_picture_caption_voting',jsonb_build_object('gameSessionId',session_record.id,'sessionRevision',next_revision)); return query select session_record.id,next_revision; end; $$;
revoke all on function public.commit_picture_caption_voting_result(uuid) from public,anon,authenticated;
grant execute on function public.cast_picture_caption_ballot(uuid,text,uuid,bigint,uuid),public.close_picture_caption_voting(uuid,uuid,uuid,bigint,boolean) to service_role;